function assetResponse(svg: string): Response {
  return new Response(svg, {
    headers: {
      'content-type': 'image/svg+xml; charset=utf-8',
      'cache-control': 'public, max-age=86400, s-maxage=2592000, immutable',
      'x-content-type-options': 'nosniff',
    },
  });
}

